-- M14: Consulting -> Software Flywheel. Customer raw content is never copied here.
CREATE TABLE "ProductizationPolicy" ("id" TEXT PRIMARY KEY,"version" TEXT NOT NULL UNIQUE,"weights" JSONB NOT NULL,"gates" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT FALSE,"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "ProductizationPolicy_active_key" ON "ProductizationPolicy"("active") WHERE "active"=TRUE;
CREATE TABLE "ProductizationObservation" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"problemCategory" TEXT NOT NULL,"problemStatement" TEXT NOT NULL,"observedOutcome" TEXT,"severity" TEXT,"frequencySignal" TEXT,"customerImpact" TEXT,"businessImpact" TEXT,"technicalImpact" TEXT,"classification" TEXT NOT NULL,"provenance" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'OBSERVED',"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductizationObservation_org_time_idx" ON "ProductizationObservation"("organizationId","createdAt");
CREATE INDEX "ProductizationObservation_source_idx" ON "ProductizationObservation"("organizationId","sourceType","sourceId");
CREATE TABLE "ProductizationPattern" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"category" TEXT NOT NULL,"normalizedProblem" TEXT NOT NULL,"who" TEXT,"what" TEXT,"when" TEXT,"why" TEXT,"workaround" TEXT,"reusableParts" TEXT,"customerSpecificParts" TEXT,"maturity" TEXT NOT NULL DEFAULT 'PATTERN_CANDIDATE',"confidence" DOUBLE PRECISION NOT NULL DEFAULT 0,"occurrenceCount" INTEGER NOT NULL DEFAULT 0,"organizationCount" INTEGER NOT NULL DEFAULT 0,"methodology" JSONB NOT NULL DEFAULT '{}'::jsonb,"m13PatternId" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductizationPattern_org_maturity_idx" ON "ProductizationPattern"("organizationId","maturity","status");
CREATE TABLE "ProductizationPatternObservation" ("patternId" TEXT NOT NULL REFERENCES "ProductizationPattern"("id") ON DELETE CASCADE,"observationId" TEXT NOT NULL REFERENCES "ProductizationObservation"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("patternId","observationId"));
CREATE TABLE "ProductizationOpportunity" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"patternId" TEXT NOT NULL REFERENCES "ProductizationPattern"("id") ON DELETE RESTRICT,"title" TEXT NOT NULL,"targetSegment" TEXT NOT NULL,"buyer" TEXT,"measurableOutcome" TEXT NOT NULL,"decisionTrack" TEXT NOT NULL DEFAULT 'UNDECIDED',"lifecycleState" TEXT NOT NULL DEFAULT 'OPPORTUNITY',"scoreTotal" INTEGER,"scoreConfidence" DOUBLE PRECISION,"scorePolicyVersion" TEXT,"evidenceQuality" INTEGER NOT NULL DEFAULT 0,"securityStatus" TEXT NOT NULL DEFAULT 'NOT_REVIEWED',"evaluationStatus" TEXT NOT NULL DEFAULT 'NOT_EVALUATED',"commercialStatus" TEXT NOT NULL DEFAULT 'UNKNOWN',"lastDecisionAt" TIMESTAMP(3),"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductizationOpportunity_org_state_idx" ON "ProductizationOpportunity"("organizationId","lifecycleState","updatedAt");
CREATE INDEX "ProductizationOpportunity_score_idx" ON "ProductizationOpportunity"("organizationId","scoreTotal");
CREATE TABLE "ProductizationEvidence" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL REFERENCES "ProductizationOpportunity"("id") ON DELETE CASCADE,"evidenceType" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"summary" TEXT NOT NULL,"classification" TEXT NOT NULL,"purpose" TEXT NOT NULL,"retentionUntil" TIMESTAMP(3),"m13CandidateId" TEXT,"evidenceHash" TEXT NOT NULL,"permissioned" BOOLEAN NOT NULL DEFAULT FALSE,"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductizationEvidence_org_opp_idx" ON "ProductizationEvidence"("organizationId","opportunityId","createdAt");
CREATE TABLE "ProductizationScore" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL REFERENCES "ProductizationOpportunity"("id") ON DELETE CASCADE,"policyVersion" TEXT NOT NULL,"metric" TEXT NOT NULL,"value" INTEGER NOT NULL,"weight" INTEGER NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"evidenceIds" JSONB NOT NULL DEFAULT '[]'::jsonb,"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ProductizationPlaybook" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL REFERENCES "ProductizationOpportunity"("id") ON DELETE RESTRICT,"name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"currentVersion" INTEGER NOT NULL DEFAULT 1,"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ProductizationPlaybookVersion" ("id" TEXT PRIMARY KEY,"playbookId" TEXT NOT NULL REFERENCES "ProductizationPlaybook"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"problem" TEXT NOT NULL,"targetCustomer" TEXT NOT NULL,"preconditions" JSONB NOT NULL,"inputs" JSONB NOT NULL,"permissions" JSONB NOT NULL,"steps" JSONB NOT NULL,"decisionPoints" JSONB NOT NULL,"humanApprovals" JSONB NOT NULL,"outputs" JSONB NOT NULL,"securityControls" JSONB NOT NULL,"successCriteria" JSONB NOT NULL,"failureConditions" JSONB NOT NULL,"rollback" JSONB NOT NULL,"estimatedEffortHours" DOUBLE PRECISION,"estimatedTimeToValueHours" DOUBLE PRECISION,"contentHash" TEXT NOT NULL,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("playbookId","version"));
CREATE TABLE "ProductizationExperiment" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL REFERENCES "ProductizationOpportunity"("id") ON DELETE CASCADE,"hypothesis" TEXT NOT NULL,"targetSegment" TEXT NOT NULL,"offer" TEXT NOT NULL,"priceMinor" INTEGER,"currency" TEXT,"durationDays" INTEGER,"successCriteria" JSONB NOT NULL,"expectedBehavior" JSONB NOT NULL,"actualBehavior" JSONB,"customerFeedback" JSONB,"conversionRate" DOUBLE PRECISION,"deliveryHours" DOUBLE PRECISION,"supportHours" DOUBLE PRECISION,"technicalCostMinor" INTEGER,"securityFindings" JSONB,"evaluationResults" JSONB,"commercialOutcome" JSONB,"decision" TEXT,"status" TEXT NOT NULL DEFAULT 'PLANNED',"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductizationExperiment_org_status_idx" ON "ProductizationExperiment"("organizationId","status","createdAt");
CREATE TABLE "ProductizationDecision" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL REFERENCES "ProductizationOpportunity"("id") ON DELETE CASCADE,"decision" TEXT NOT NULL,"fromState" TEXT NOT NULL,"toState" TEXT NOT NULL,"rationale" TEXT NOT NULL,"evidenceIds" JSONB NOT NULL DEFAULT '[]'::jsonb,"decisionOwnerUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductizationDecision_opp_idx" ON "ProductizationDecision"("opportunityId","createdAt");
CREATE TABLE "ProductizationMetric" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"opportunityId" TEXT,"metric" TEXT NOT NULL,"value" DOUBLE PRECISION,"unit" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT,"confidence" DOUBLE PRECISION NOT NULL DEFAULT 1,"isEstimate" BOOLEAN NOT NULL DEFAULT FALSE,"observedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductizationMetric_org_metric_idx" ON "ProductizationMetric"("organizationId","metric","observedAt");
INSERT INTO "ProductizationPolicy" ("id","version","weights","gates","active") VALUES ('m14-policy-v1','m14-policy-v1','{"recurrence":14,"customer_pain":10,"economic_value":10,"willingness_to_pay":10,"solution_repeatability":12,"delivery_repeatability":10,"automation_feasibility":8,"security_feasibility":10,"market_breadth":8,"evidence_quality":8}','{"recurrenceValidated":{"minimumIndependentOrganizations":2,"minimumProblemSimilarity":70,"minimumSolutionSimilarity":70},"promotion":{"minimumScore":60,"minimumEvidenceQuality":60},"productValidated":{"requiresEvaluationPass":true},"productized":{"requiresSecurityPass":true,"requiresEvaluationPass":true}}',TRUE) ON CONFLICT("version") DO NOTHING;
ALTER TABLE "ProductizationObservation" ADD CONSTRAINT "ProductizationObservation_classification_ck" CHECK ("classification" IN ('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED','SECRET'));
ALTER TABLE "ProductizationPattern" ADD CONSTRAINT "ProductizationPattern_maturity_ck" CHECK ("maturity" IN ('OBSERVED','NORMALIZED','PATTERN_CANDIDATE','RECURRENCE_VALIDATED','OPPORTUNITY'));
ALTER TABLE "ProductizationOpportunity" ADD CONSTRAINT "ProductizationOpportunity_state_ck" CHECK ("lifecycleState" IN ('OBSERVED','NORMALIZED','PATTERN_CANDIDATE','RECURRENCE_VALIDATED','OPPORTUNITY','PLAYBOOK_CANDIDATE','PLAYBOOK_VALIDATED','AUTOMATION_CANDIDATE','AUTOMATION_VALIDATED','PRODUCT_CANDIDATE','PRODUCT_EXPERIMENT','PRODUCT_VALIDATED','PRODUCTIZED','SCALED','REJECTED','DEFERRED','DUPLICATE','INSUFFICIENT_EVIDENCE','NOT_REPEATABLE','NOT_ECONOMIC','SECURITY_BLOCKED','CUSTOMER_SPECIFIC','SUPERSEDED','RETIRED'));
ALTER TABLE "ProductizationEvidence" ADD CONSTRAINT "ProductizationEvidence_classification_ck" CHECK ("classification" IN ('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED','SECRET'));
